ids = ["YM-069","YM-070","YY-006","YY-010","YY-011","YY-012","YY-013","YY-014","YY-015","YY-016","YY-017","YY-018","YY-019","YY-020","YY-021","YY-022","YY-023","YY-024","YY2-001","YY2-002"]
assert set(P) == set(ids), (set(ids)-set(P), set(P)-set(ids))
for cid in ids:
    p = OUT / f"{cid}.json"
    p.write_text(json.dumps(P[cid], ensure_ascii=False, indent=1), encoding="utf-8")
    back = json.loads(p.read_text(encoding="utf-8"))
    assert back["case_id"] == cid and set(back) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert back["basis"].splitlines()[0] == "tradition: liuyao"
    print(cid, p.stat().st_size)
print("changed_main", sum(P[c]["trigger"]["changed_main"] for c in ids))
print("reserve_used", sum(P[c]["trigger"]["reserve_used"] for c in ids))
print("disputed", sum(P[c]["trigger"]["disputed"] for c in ids))
print("total", len(ids))
